  "site.v5.ledger.detail-proposed": "{id} \xB7 {capability}",
  "site.v5.ledger.verb-decided": "entschieden",
  "site.v5.ledger.verb-approved": "genehmigt",
  "site.v5.ledger.detail-approved": "einmalig \xB7 unterzeichnet J. Okafor",
  "site.v5.ledger.verb-sealed": "versiegelt",
