  "legal.subprocessors.fields.processes": "D\xF3nde lo procesa",
  "legal.subprocessors.fields.safeguard": "En qu\xE9 se apoya la transferencia",
  "legal.subprocessors.fields.status": "Por qu\xE9 tiene ese estado",
  "site.v5.meta.title": "P\xE1gina de inicio v5 \xB7 {brand}",
  "site.v5.provenance-badge": "SIMULADO",
  "site.v5.person.jo-owner": "J. Okafor \xB7 Titular",
  "site.v5.nav.landmark": "Principal",
  "site.v5.nav.link.scope": "Alcance",
  "site.v5.nav.link.exhibit": "Expediente",
  "site.v5.nav.link.proof": "Prueba",
  "site.v5.nav.link.control": "Control",
  "site.v5.nav.link.record": "Registro",
  "site.v5.nav.waitlist-open": "LISTA DE ESPERA ABIERTA",
  "site.v5.hero.title-soft": "Su empresa,",
  "site.v5.hero.title-hard": "funcionando",
  "site.v5.hero.lead": "{brand} convierte sus objetivos en acciones, ejecuta el trabajo y verifica cada resultado. Usted mantiene el control.",
  "site.v5.hero.replay": "Haga pasar una acci\xF3n por \xE9l",
  "site.v6.hero.title-word": "sola",
  "site.v6.hero.title-tail": ".",
  "site.v6.stream.proposal-1": "Reclamar las cuatro facturas que vencieron esta semana",
