  "brand.title": "Marca",
  "brand.nav.blurb": "La marca, los tipos de letra, y c\xF3mo referirse a nosotros.",
  "departments.engineering.title": "Ingenier\xEDa",
  "departments.marketing.title": "Marketing",
  "departments.leads.title": "Contactos",
  "departments.support.title": "Soporte",
