  "site.v5.provenance-badge": "SIMULADO",
  "site.v5.person.jo-owner": "J. Okafor \xB7 Propriet\xE1rio",
  "site.v5.nav.landmark": "Principal",
  "site.v5.nav.link.scope": "Escopo",
  "site.v5.nav.link.exhibit": "Exibi\xE7\xE3o",
